void bucket_add_partition_point(std::vector<float>& hash_points, float point) {
    auto it = std::lower_bound(hash_points.begin(), hash_points.end(), point);
    hash_points.insert(it, point);
}

// Test case
int main() {
    std::vector<float> hash_points = {1.0f, 2.0f, 4.0f, 5.0f};
    bucket_add_partition_point(hash_points, 3.0f);
    // hash_points should now be {1.0f, 2.0f, 3.0f, 4.0f, 5.0f}
    return 0;
}
